import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Проблемы игрока","description":"","frontmatter":{"pageId":"players/troubleshooting","contentRevision":5},"headers":[],"relativePath":"ru/players/troubleshooting.md","filePath":"ru/players/troubleshooting.md"}'),o={name:"ru/players/troubleshooting.md"};function i(l,t,n,s,h,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="проблемы-игрока" tabindex="-1">Проблемы игрока <a class="header-anchor" href="#проблемы-игрока" aria-label="Permalink to &quot;Проблемы игрока&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Симптом</th><th>Что проверить</th></tr></thead><tbody><tr><td>Нет Мультиплеера</td><td>Версии игры/Harmony, список модов, вложенные папки</td></tr><tr><td>Отказ сертификата</td><td>Адрес, время системы, подтверждённый pin; не отключать TLS</td></tr><tr><td>Различия модов</td><td>Порядок, версии, hash, настройки; применить пакет с закрытой игрой</td></tr><tr><td>Вещи не отправляются</td><td>Консоль/маяки, доступность предметов, долг, угроза, заморозка</td></tr><tr><td>Live завис после обрыва</td><td>Дождаться переподключения, проверить связь хозяина, запросить снимок</td></tr><tr><td>Coop занят</td><td>Один активный партнёр, хозяин дома онлайн, назначены допустимые пешки</td></tr></tbody></table><p>Сначала сохрани свидетельства ошибки: точное сообщение, время, сервер, действие и id операции. Экспорт диагностики создаёт локальный ZIP; проверь содержимое перед самостоятельной отправкой администратору.</p><h3 id="получить-локальныи-отчет" tabindex="-1">Получить локальный отчёт <a class="header-anchor" href="#получить-локальныи-отчет" aria-label="Permalink to &quot;Получить локальный отчёт&quot;">​</a></h3><ol><li>Открой <strong>Мультиплеер → Диагностика</strong> в списке серверов или диагностику из игрового оверлея Rimlink. Снимок делается при открытии; закрой и открой окно для обновления.</li><li>Проверь предпросмотр и нажми <strong>Сохранить локальный ZIP</strong>. Путь показывается до сохранения, имя файла — после. Отчёт находится в <code>Rimlink/Diagnostics</code> внутри каталога save-data игры; ZIP содержит diagnostics.json и ограниченный events.log без свободного текста сообщений.</li><li>Для Windows стандартная папка профиля — <code>%USERPROFILE%/AppData/LocalLow/Ludeon Studios/RimWorld by Ludeon Studios</code>; игровой журнал отдельно лежит в <code>Logs/Player.log</code>. При собственном -savedatafolder ищи данные там. Отчёт не включает этот журнал; согласуй отдельно безопасную выдержку, если она нужна.</li></ol><h2 id="triage" tabindex="-1">Диагностика по этапу, а не переустановка всего <a class="header-anchor" href="#triage" aria-label="Permalink to &quot;Диагностика по этапу, а не переустановка всего {#triage}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Этап</th><th>Признак</th><th>Безопасная проверка</th></tr></thead><tbody><tr><td>Запуск</td><td>Нет Multiplayer</td><td>Мод включён, Harmony/версия/папка, свежий лог</td></tr><tr><td>TLS</td><td>Изменён отпечаток</td><td>Адрес, часы, подтверждение администратора</td></tr><tr><td>Вход</td><td>Неверный пароль/бан</td><td>Точный метод и аккаунт, не чужие credentials</td></tr><tr><td>Сборка</td><td>Mismatch</td><td>Категория diff, путь конфликтной копии</td></tr><tr><td>Домашняя карта</td><td>Старая/reset-версия</td><td>Серверный сейв, generation/epoch, причина отказа</td></tr><tr><td>Экономика</td><td>Unknown response</td><td>Исходный запрос, почта, журнал; не новый перевод</td></tr><tr><td>Live</td><td>Ожидание/отставание</td><td>Хозяин online дома, состояние потока, fresh snapshot</td></tr></tbody></table><p>В отчёте нужны время с зоной, сервер, версия, действие, точный отказ и id операции. Пароль, Steam-ticket и API-token не нужны. Полный Player.log может раскрывать личные пути и данные других модов.</p><h2 id="escalate" tabindex="-1">Когда остановиться и передать данные администратору? <a class="header-anchor" href="#escalate" aria-label="Permalink to &quot;Когда остановиться и передать данные администратору? {#escalate}&quot;">​</a></h2><p>Остановись при изменённом неподтверждённом pin, отсутствии доказательств replay, повторном отказе загрузки после rollback или внешне изменённых файлах установки. Сохрани локальную папку и диагностический ZIP, не редактируй доказательства для «чистого» лога.</p><p>Запиши, воспроизводится ли ошибка после повторного входа и какие шаги уже выполнены. Администратору сначала отправь минимальный отчёт и безопасно отобранные строки [Rimlink]. Полную папку сейвов/журналов передавай только отдельным согласованным способом. Встроенный ZIP сам ничего не загружает в сеть.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Диагностика не загружается автоматически и не включает Player.log/произвольные логи. Логи игры могут содержать личные данные: не публикуй целиком. Не удаляй восстановительные журналы и не принимай неизвестные сертификаты.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./connect">Подключение и вход</a></li><li><a href="./saves-recovery">Сохранения и восстановление</a></li><li><a href="./../admins/troubleshooting">Проблемы администратора</a></li></ul>',17)])])}const b=a(o,[["render",i]]);export{u as __pageData,b as default};
